/bin/bash -lc "node --input-type=module <<'EOF'
import http from 'node:http'
import { spawn } from 'node:child_process'
import { once } from 'node:events'

const events = []
const analytics = http.createServer((request, response) => {
  let body = ''
  request.on('data', chunk => { body += chunk })
  request.on('end', () => {
    events.push(JSON.parse(body))
    setTimeout(() => { response.writeHead(204).end() }, 1500)
  })
})
analytics.listen(0, '127.0.0.1')
await once(analytics, 'listening')
const analyticsPort = analytics.address().port

const portProbe = http.createServer()
portProbe.listen(0, '127.0.0.1')
await once(portProbe, 'listening')
const appPort = portProbe.address().port
await new Promise(resolve => portProbe.close(resolve))

const app = spawn('npm', ['run', 'start', '--', '-p', String(appPort)], {
  cwd: '/workspace',
  env: { ...process.env, ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analyticsPort}/events`, NEXT_TELEMETRY_DISABLED: '"'1' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let appOutput = ''
app.stdout.on('data', chunk => { appOutput += chunk })
app.stderr.on('data', chunk => { appOutput += chunk })
try {
  let ready = false
  for (let attempt = 0; attempt < 100; attempt++) {
    try {
      const response = await fetch("'`http://127.0.0.1:${appPort}/_not-found`)
      if (response.status === 404) { ready = true; break }
    } catch {}
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  if (!ready) throw new Error(`App did not start: ${appOutput}`)

  const started = performance.now()
  const response = await fetch(`http://127.0.0.1:${appPort}/`)
  const html = await response.text()
  const elapsed = Math.round(performance.now() - started)
  await new Promise(resolve => setTimeout(resolve, 2000))
  const sent = events.find(event => event.event === '"'page_view' && event.path === '/')
  if (response.status "'!== 200 || !html.includes('"'Welcome to our site.') || "'!sent || elapsed >= 1500) {
    throw new Error(JSON.stringify({ status: response.status, welcome: html.includes('"'Welcome to our site.'), sent, elapsed }))
  }
  console.log(JSON.stringify({ responseMs: elapsed, analyticsDelayMs: 1500, event: sent }))
} finally {
  app.kill('SIGTERM')
  analytics.close()
}
EOF"
